-- 2. DAILY CHECKLIST (old "KPI"): the full live history. A day someone has
-- already re-marked in Atlas (recordedBy set) is left as they saved it.
INSERT INTO "StaffChecklistItem" (id, "storeId", key, label, sort, "isActive", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1), v.key, v.label, v.sort, true, now(), now()
  FROM (VALUES ('attendance', 'Present', 0), ('leave', 'On leave', 1), ('in_time', 'On time', 2), ('whatsapp_update', 'WhatsApp update sent', 3), ('in_dress_code', 'In dress code', 4)) AS v(key, label, sort)
 WHERE (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) IS NOT NULL ON CONFLICT ("storeId", key) DO NOTHING;
