  ) AS v(uid, work_date, vals, ref)
  JOIN "User" u ON u."legacyRef" = 'LEGACY_USER:' || v.uid
 WHERE (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) IS NOT NULL
ON CONFLICT ("storeId", "userId", "workDate") DO UPDATE SET "values" = EXCLUDED."values", "legacyRef" = EXCLUDED."legacyRef", "updatedAt" = now()
 WHERE "StaffChecklistEntry"."recordedBy" IS NULL;
