  ) AS v(ref, ordno, status, slip, remark, terms, dispatched, completed, created)
  LEFT JOIN "SalesOrder" so ON so."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND so."legacyRef" = v.ordno
 WHERE (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) IS NOT NULL
   AND NOT EXISTS (SELECT 1 FROM "InstallationChallan" x WHERE x."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND (x."legacyRef" = v.ref OR x."challanNo" = v.ref));
