  JOIN "InstallationChallan" i ON i."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND i."legacyRef" = v.ref
  LEFT JOIN "Product" p ON p."storeId" = i."storeId" AND p."productCode" = v.pcode
 WHERE NOT EXISTS (SELECT 1 FROM "InstallationChallanItem" x WHERE x."challanId" = i.id);
