  JOIN "Complaint" c ON c."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND c."legacyRef" = v.cno
  LEFT JOIN "User" u ON u."legacyRef" = 'LEGACY_USER:' || v.uid
 WHERE NOT EXISTS (SELECT 1 FROM "ComplaintActivity" x WHERE x."complaintId" = c.id AND x.kind = 'legacy_update' AND x."createdAt" = v.at AND x.body = v.body);
