  ) AS v(lcode, body, at, uid)
  JOIN "Lead" l ON l."storeId" = (SELECT s.id FROM "Store" s JOIN "Organization" o ON o.id = s."organizationId"
     WHERE o.name ILIKE '%vcare%' OR o.name ILIKE '%v.care%'
     ORDER BY (SELECT count(*) FROM "Invoice" i WHERE i."storeId" = s.id) DESC LIMIT 1) AND l."leadCode" = v.lcode
  LEFT JOIN "User" u ON u."legacyRef" = 'LEGACY_USER:' || v.uid
 WHERE NOT EXISTS (SELECT 1 FROM "LeadNote" x WHERE x."leadId" = l.id AND x."createdAt" = v.at AND x.body = '[Old system] ' || v.body);
